) AS (
  VALUES 
    (249::BIGINT, 'Demasiado aburrido y no enseña nada.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-10-10T00:00:00+00:00'::TIMESTAMPTZ, '145f4cd4efb0bdf9c0f95defd5b706c88ba0e6fa3140cb8feeefd42dbcc1ad1b'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Lo mejor es ir a la clase por que luego en los examenes hace preguntas de comentarios que el hace'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '1fadda0b9aa7bef00e7e08c24267e390563623cc763ad45fa18fa5ab9d0c1004'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Un curso muy bonito e interesante para que este mae lo de la verdad, como en otros comentarios es un vende humo, no se aprende nada, y aveces los labs ni se hacen. Es cierto que es fácil pasar, pero da lástima que un curso así se pierda sin aprender nada.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-07-26T00:00:00+00:00'::TIMESTAMPTZ, 'b419794e0957f3f530cca1b3b0ed5d85b53ea2bf093eb68b6f036d47d6ee8aa0'::TEXT, ARRAY[956]::BIGINT[]),
    (249::BIGINT, 'No es obligatoria la asistencia, pero existe la posibilidad de que deje una tarea que vale el 2o% de la nota y no lo deja hacerla a menos que tenga justificacion de la falta, pero al parecer es flexible si es por trabajo. El curso es pesado, pero con medio estudiar antes del examen se pasa bien'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, '65e701bfc34e14f6e0e5cb403904d55ccfeb4e5cb69b4f690559961cbefa09a6'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'El profe es una teja y el curso es bastante relajado con él, es muy inspirado y se nota que le gusta lo que hace, lo recomiendo 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '3bb6f10491e3ed635851be43b728eca991f08f740714361af31830e724f4e869'::TEXT, ARRAY[956]::BIGINT[]),
    (249::BIGINT, 'El profe no entrega las evaluaciones a tiempo por lo que incumple con el reglamento. Habla mucho y a algunos les gusta eso pero fácilmente podría ser considerado un vende humo. Es un curso totalmente desaprovechado, una verdadera lástima.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '80b06fe70a0beca90e4566448d2795deff8b5a558ccf3935a0c37bdee9cef92f'::TEXT, ARRAY[956]::BIGINT[]),
    (249::BIGINT, 'Si quiere pasar matricule con el, pero no va a apender nada, NADA. Es una excelente persona pero siempre tiene una excusa no dar los laboratorios.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '9dea2340039be8cca0231a9ef1ddd5d7c7b932db932c137ae2b37f1339f1ee3d'::TEXT, ARRAY[956]::BIGINT[]),
    (249::BIGINT, 'Con matricular sepa que ya pasó, no va a aprender absolutamente nada pero el profe es super buena gente e intenta que el lab sea super liviano, los examenes son para la casa y son ejercicios que él mismo ha resuelto pero con datos diferentes y no se hacen reportes de lab'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'b74c3467c6f750e0641734c2e97eab5f9488452698cf563acf1984ee2d6ee797'::TEXT, ARRAY[956]::BIGINT[]),
    (249::BIGINT, 'VAGO, NO METAN CON ÉL. COMO PERSONA ES MUY RESPETUOSO Y AMABLE (LAVIOSO) PERO COMO PROFESOR ES UNA BASURA, ES MUY VAGO'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-22T00:00:00+00:00'::TIMESTAMPTZ, '2b6ab37e6e34cd7be6ae643f45c797f49e4fa8366eb4dac8bc1fb0e12ce85e7c'::TEXT, ARRAY[983]::BIGINT[]),
    (249::BIGINT, 'No matricule con el, es buena persona pero no hace literal nada, en virtual no sirve, solo lee pdfs y ya las ultimas clases ni apareció, nunca explico los programas que se usaron, es autodidacta prácticamente.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, '874f26cbe17fbe0ef2142803c1667d5a0130e7814dc05da7a78983ff2479df07'::TEXT, ARRAY[610]::BIGINT[]),
    (249::BIGINT, 'El curso realmente se pasa solo, las evaluaciones (quices, exámenes) son muy fáciles. Solo es cuestión de prestar atención en clase y no tendrá que estudiar para hacer las.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Brinda apoyo']::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, '6b6b0d92eb52e6bd84911abdb82894f61ea32e03f232b34242975596d947999f'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'En virtual el curso se pasa solo, quices demasiado fáciles y exámenes también, aburrido porque da todo el periodo de la clase, pero nada grave la verdad, lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'e5cc18d5ffcca9aaa77ea777d8fd68ac85100d822276609b2fcc672c36eb906b'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Se me hizo un curso muy interesante y el profe superr apasionado realmente se nota que ama lo que hace, aunque son clases largas con un buen cafecito se te hace un rato muy agradable e interesante, algunos exámenes podían ser complicados pero se equilibraba con quices muy fáciles'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-07T00:00:00+00:00'::TIMESTAMPTZ, '39662de18e8f42bd06d17338727cf1e5fb11665f2e8acb12c98bad99ae7fe5fd'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Las clases si son largas (al menos virtualmente) porque tarda las 4 horas, pero da bastantillo de receso. El mae es super buena gente y pasa tratando de que todos entiendan, pasa resolviendo dudas y demás. No se hicieron quices solo reportes y los exámenes que todo fue super sencillo también'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-25T00:00:00+00:00'::TIMESTAMPTZ, '150e1421016fb2ba06e5c5504fc460986dcf7d8769e83385d1dea7cc637a4785'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'ES DEMASIAAAAAAADO ABURRIDO, DEMASIAAAAAAADO XD'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-12T00:00:00+00:00'::TIMESTAMPTZ, 'fc968903c53d05385eff3a7024e48e322e03832841821d6ed4e9e7a488fbf74b'::TEXT, ARRAY[956]::BIGINT[]),
    (249::BIGINT, 'Es muy fácil, pero no se aprende nada'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '75b98f567f5ff18c38c64f5bd32f41084495dab03d3658f74e030102ed78edd5'::TEXT, ARRAY[956]::BIGINT[]),
    (249::BIGINT, 'Es muy buena gente, pero en virtual es malisimo como profe. Solo lee presentaciones repetitivas y no se aprende nada de diseño. Si quieren aprender algo, mejor llevar otra electiva.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-10T00:00:00+00:00'::TIMESTAMPTZ, '247dcf9374cd0c09afb937c33c70b41f7d80005e8eddd0ae0d651e566e20d61e'::TEXT, ARRAY[988]::BIGINT[]),
    (249::BIGINT, 'Como persona el profe es muy bueno, en cambio en el curso sí me decepcionó bastante, 16 semanas de pura teoría repetitiva, lee las presentaciones y es imposible prestarle atención. En resumen, no se aprende NADA.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-06-08T00:00:00+00:00'::TIMESTAMPTZ, '7a44303d6226860ee1f0ff36ee4d255e0c1b4e902c826a3769f46fdbacb67aa0'::TEXT, ARRAY[988]::BIGINT[]),
    (249::BIGINT, 'Excelente profe, se nota que le gusta la materia, es una persona muy respetuosa y siempre trata de ayudar a los estudiantes. El curso sí me decepcionó un poco porque las 16 semanas fueron de solo teoría repetitiva y aburrida, nada de diseño por lo que el curso no se aprovechó de la mejor forma.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '7e9c7d3af7bdecb9d88e6a83f0e4f3ba66ede92bcc93c108dbe5c20bc099e66d'::TEXT, ARRAY[983]::BIGINT[]),
    (249::BIGINT, 'Es un buen profe y explica muy bien la materia, sin embargo, la mayoría de clases son largas (dura las 4 horas) y se torna un poco aburrido. Los quices, tareas y exámenes son súper fáciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '93cf0ad363f774a013951266d40eb13747918cb93bc78e408a683653fb38ef86'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Es un profe muy considerado y se nota que le gusta la materia que da, trata de no hacer el curso tan tedioso ya que es mucha materia. Clases bastante largas, pero evaluaciones virtuales fáciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '8e45ec369b2dffb7de5f41f28ff896dd4b9bf96d6fe843b7400f5695e20607b5'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'El profesor es súper amable y considerado. Se nota su vocación y profesionalidad en cada clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, 'b57af912d27b5cfeb2029cc94bd50d70ef8fb0df8c23015b7e2d093559e5f29c'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Se nota que tiene demasidad pasión por lo que hace, excelente para interacturar y motivar a las personas, talvez nada más mencionar que algunas, pero muy pocas, veces anda muy ajetreado ya que como es tan bueno está metido en todo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-22T00:00:00+00:00'::TIMESTAMPTZ, '4de02d9ee25c941d15e9c0c7f65d43f899fceba6a11e8b6f1060adf7890ad01c'::TEXT, ARRAY[956]::BIGINT[]),
    (249::BIGINT, 'Demasiado fácil con Óscar. Transmite una pasión exorbitante, es increíble como un profesor te cuenta como preparó la clase. 10/10 Lo mejor de esa escuelucha.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2019-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'c5a89910e50c3a06d74f5cc65e99858a2141114087d0969a12010cba81566519'::TEXT, ARRAY[610]::BIGINT[]),
    (249::BIGINT, 'Excelente profesor y hace giras muy chivas'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2019-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'dc201edeec012f5db930b9bb1c293d904523c38e1141e7f00324fbf56b7b644d'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Si tiene la oportunidad de llevar el curso con él, no lo dude, no es exigente en la calificación, se toma el tiempo para no hacer la clase aburrida y tiene consideración con las tareas de 1%. Muy buen profesor'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-05T00:00:00+00:00'::TIMESTAMPTZ, '5983572b1196893285fbf2f01beed4f0a9e5cfe4a805b7862a11a04d8ca8d5e6'::TEXT, ARRAY[610]::BIGINT[]),
    (249::BIGINT, 'Le encanta lo que hace, intenta que el estudiante se apasione por la materia. Sin embargo senti que pude haber sacado mas provecho del curso, ya que en algunos casos no cubre por completo temas o los ejercicios que deja no refleja la complejidad de los programas usados.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '1f466962da699ee17a560ee5ff33e85caf0c0eedbd07f3ddbb11191d002a95f1'::TEXT, ARRAY[610]::BIGINT[]),
    (249::BIGINT, 'Es mucha materia pero el profe hace el curso lo más liviano posible, sus clases no son taaan aburridas como podrían ser con otro profe. Exámenes fáciles El profe es excelente y se nota que ama su trabajo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'e48f237d447966735f3a11b59cec69b8391757d50f11de674892e403fac139b3'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'El curso tiene demasiada materia, pero demasiada, sin embargo el profe trata de hacer las clases amenas y trata de no hacerlas tan pesadas. Explica demasiado bien y es un excelente profe! Realmente el mejor para este curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-08-28T00:00:00+00:00'::TIMESTAMPTZ, 'afe0cb0019061aa35484339143ac94a5090118954106228e361d4cf54bf77c8e'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Es mucha la materia del curso, por eso es bueno hacer un documento que tenga la materia resumida porque sube muchas presentaciones al Tecdigital, pero el curso en sí no es complicado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '209631fd8b85c5db0fe21c1ca196f819067a9ccc2031cf78b37156a03ae01a8f'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Hay demasiada teoría abarcada muy poco tiempo, pero es muy interesante. Ese profe es lo mejor, gracioso, conciso (resume la materia que uno debe saber), laboratorios como entre 7 personas. A veces hay gira (chiva).'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '81d73792e16d48db2ff6846d8c2e831ff6ca8862cd3eb17b1f7b60f4fd0ac4a0'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Demasiada materia, primer parcial fácil pero el segundo lo hace a matar. Pocos quices y no deja tareas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'a0a0939560e412577e39d6889aacbabd79417c1968bb22fa6e2513609ab3ed1f'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'El curso es muchísima materia por lo que es pesado, pero el profe trata de hacerlo dinámico y se preocupa porque uno aprenda. Muy recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2019-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'aecf28846d65e755a57b9ce41f2189ea27d3bcc593b9c30c0e4731ef37d9ba0c'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Excelente profesor. Muy claro y se interesa bastante por que la clase sea amena ya que es muy larga. Hay que estudiar bastante ya que es mucha materia y los exámenes por lo general son muy puntuales.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, '2a73b3f915473b2613a38a93a216c93943e285125bfbbcb8f227e62706834d87'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Muy tuanis el profesor que se preocupa por los estudiantes y hace todo lo posible para que las clases sean amenas, ya que son largas. Los exámenes son fáciles, pero hay que estudiar bastante porque es mucha materia.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases largas']::TEXT[], '2018-11-21T00:00:00+00:00'::TIMESTAMPTZ, '2c89e107cc6ba34f81e2e8fe71f1f3611702bc5da1e6edebec6305fb986e58ac'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'El curso tiene mucha materia y las clases son muy largas pero a pesar de eso el profe se esfuerza en mantener la clase interesante. Es un excelente profesor que se interesa por los estudiantes. Los exámenes son difíciles debido a la cantidad de materia que entra.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '718ad4b5c71becd046f9a0d3cac3ea5270e2c5a7d5481d7d685bf78fa91d1d3d'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Muy buen profesor, excelente persona, se aprende. Exámenes con preguntas voladas... pero curso pasable.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '7f2bce4a1ca91110578d2f8028f784499e7b463b26d94d240c0d6e7c58026aae'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Muy buen profe, aunque en lo exámenes pregunta lo que sea...'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-09T00:00:00+00:00'::TIMESTAMPTZ, '7828b038ae0eb653d374ad7b190aed3f706258e66f4a2e020f7c81b83cf17125'::TEXT, ARRAY[1733]::BIGINT[]),
    (249::BIGINT, 'Excelente profesor y excelente persona, sabe demasiado de la materia, aunque los exámenes son medio volados, pregunta todo todo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-16T00:00:00+00:00'::TIMESTAMPTZ, 'a85a635dc239ced272b39d5b279b5ae8a3ae7e0973c0153cd79c9d0aecb8eee4'::TEXT, ARRAY[2783, 2883]::BIGINT[]),
    (249::BIGINT, 'De lo mejorcito de la Escuela, no duden en matricular con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, '82b7982744313a9cc46fc23d912329c0b1e22dc41dd870255eb2d3a5a33a8a0b'::TEXT, ARRAY[983]::BIGINT[]),
    (249::BIGINT, 'Excelente profe, pero pregunta cualquier cosa'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'f20c477ce6133411c2c4c5e33818a9766ee929ad583ade3b892b112e701b55fd'::TEXT, ARRAY[983]::BIGINT[]),
    (249::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, '9bd405565582f18dcc30b6905f650a124bbd0fe5966cd3c45b30ef281ea31bc7'::TEXT, ARRAY[972, 983]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
